x <- sample(1:7,520,replace=TRUE)

1.
x <- ifelse(x<=2,"low",
            ifelse(x>=3&x<=5,"medium",
                   "high")
            )

2. 這是迴圈+if判斷式
y <- as.character()
for(i in 1:520){
  if(x[i] <=2){
    y[i] <- "low"
  }else if(x[i]>=3 & x[i]<=5){
    y[i] <- "medium"
  }else{
    y[i] <- "high"
  }
}

3.這是判斷符合條件的位置給值
x[x %in% 1:2] <- "low"
x[x %in% 3:5] <- "medium"
x[x %in% 6:7] <- "high"

